    h = g.get("grid_height", 0) or 0

    def pos(v):
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return [v["x"], v["y"]]
            for k in ("pos", "position", "loc", "xy"):
                if k in v:
                    p = pos(v[k])
                    if p is not None:
                        return p
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            x, y = v[0], v[1]
            if isinstance(x, (int, float)) and isinstance(y, (int, float)):
                return [x, y]
        return None

    def pts(v):
        p = pos(v)
        if p is not None:
            return [p]
        out = []
        if isinstance(v, dict):
            for a in v.values():
                out.extend(pts(a))
        elif isinstance(v, (list, tuple)):
            for a in v:
                out.extend(pts(a))
        return out

    s = pos(g.get("self_position")) or [0, 0]
    o = pos(g.get("opponent_position")) or [0, 0]
    rs = pts(g.get("resources"))
    obs = {tuple(p) for p in pts(g.get("obstacles"))}
    if tuple(s) in obs:
        obs.remove(tuple(s))

    cand = [(1,0),(-1,0),(0,1),(0,-1),(0,0)]
    best = (None, -10**9)
    for dx, dy in cand:
