        if rs:
            d1 = min(abs(x - p[0]) + abs(y - p[1]) for p in rs)
            d0 = min(abs(s[0] - p[0]) + abs(s[1] - p[1]) for p in rs)
            score += (d0 - d1) * 10
        score += abs(s[0] - o[0]) + abs(s[1] - o[1])
        score -= abs(x - o[0]) + abs(y - o[1])
        if g.get("remaining_resource_count", 0) <= 1 and rs:
            score += 3 if any(abs(x-p[0]) + abs(y-p[1]) == 0 for p in rs) else 0
        if score > best[1]:
            best = ((dx, dy), score)

    if best[0] is not None:
        return [best[0][0], best[0][1]]

